public class Aviao extends MeioDeTransporte implements Internacional,Reabastecivel { private double combustivel=1000; public Aviao(){super("Avião",220,850,15.0);} public void partir(String d){System.out.println("Avião partindo para "+d);} public void verificarDocumentacao(){System.out.println("Documentação internacional verificada.");} public String getPaisOrigem(){return "Brasil";} public String getPaisDestino(){return "Portugal";} public void reabastecer(double l){combustivel+=l;} public double getCombustivel(){return combustivel;} }
